import{_ as t,c as n,a1 as i,o}from"./chunks/framework.nlCHK0Xf.js";const r="/2.jpg",a="/3.jpg",s="/4.jpg",l="/5.jpg",c="/6.jpg",p="/7.jpg",u="/8.jpg",y=JSON.parse('{"title":"Quick Setup","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"starter/2 Quick Setup.md","filePath":"starter/2 Quick Setup.md"}'),h={name:"starter/2 Quick Setup.md"};function g(d,e,f,m,P,_){return o(),n("div",null,e[0]||(e[0]=[i('<h1 id="quick-setup" tabindex="-1">Quick Setup <a class="header-anchor" href="#quick-setup" aria-label="Permalink to &quot;Quick Setup&quot;">​</a></h1><p><img src="'+r+'" alt="Puffin connector"><img src="'+a+'" alt="Puffin connector"> This section will guide you through the process of setting up your Puffin.</p><h3 id="connecting-the-hardware" tabindex="-1">Connecting the Hardware <a class="header-anchor" href="#connecting-the-hardware" aria-label="Permalink to &quot;Connecting the Hardware&quot;">​</a></h3><p>There are 24 extension pins on the Puffin board. The most relevant pins for our setup are:</p><ul><li><strong>GND</strong>: pin 1, pin 2</li><li><strong>Vcc in</strong>: pin 3, pin 4</li><li><strong>Serial port</strong>: pin 22, pin 24, pin 19, pin 21</li><li><strong>PWM (6 channels)</strong>: <ul><li>PWM1: Pin 6</li><li>PWM2: Pin 5</li><li>PWM3: Pin 11</li><li>PWM4: Pin 18</li><li>PWM5: Pin 15</li><li>PWM6: Pin 17</li></ul></li></ul><h3 id="step-by-step-setup" tabindex="-1">Step-by-Step Setup <a class="header-anchor" href="#step-by-step-setup" aria-label="Permalink to &quot;Step-by-Step Setup&quot;">​</a></h3><ol><li><p><strong>Insert the SD card</strong> Begin by inserting the SD card into the designated slot on the Puffin. This card will store important data and files required for the Puffin&#39;s operation. If you are using the 4G version of the Puffin, also insert the SIM card into its respective slot. <img src="'+s+'" alt="Puffin connector"></p></li><li><p><strong>Connect the MIPI camera</strong> Connect mipi camera to the Puffin. Ensure that the camera is securely attached and properly aligned with the Puffin&#39;s mipi camera interface. <img src="'+l+'" alt="Puffin connector"></p></li><li><p><strong>Connect the appropriate antennas to your Puffin</strong></p><ul><li>For the <strong>WiFi version</strong>,connect WIFI antenna to the designated connector on the board. <img src="'+c+'" alt="Puffin connector"></li><li>For the <strong>4G/GPS version</strong>, connect LTE antenna and GPS antenna to their respective connectors. <img src="'+p+'" alt="Puffin connector"></li></ul></li><li><p><strong>Connect power</strong>: <img src="'+u+'" alt="Puffin connector"></p><ul><li>The included power cable can be used with a PC or any power source with a USB port. The input voltage should be between 4V and 16V. You can also use a LiPo battery as a power source, and we provide a power table for easy setup.</li></ul></li><li><p><strong>Connect to the internet</strong>:</p><ul><li><strong>4G version</strong>: If you are using a 4G version puffin board, you are all set with a sim card plugged in! The puffin board is already online.</li><li><strong>WiFi version</strong>: If you are using a wifi board, please refer to the section about how to connect to wifi.</li><li><strong>Additional Tips</strong>: Double-check all connections to ensure they are secure and properly aligned. Handle the components with care to avoid any damage. If you encounter any issues during the setup process, refer to the troubleshooting section or reach out to our support team for assistance.</li></ul></li></ol>',7)]))}const S=t(h,[["render",g]]);export{y as __pageData,S as default};
